# AiBeast menu: the common actions without typing a command.
# Usage: double-click AiBeast-Menu.bat (menu), or a direct shortcut (AiBeast-Images.bat, AiBeast-Normal.bat...).
# Prerequisites: the SSH key and the "Host aibeast" entry generated by "lab client" on AiBeast (see docs\remote-access.md).
# (Function names are French, as in the original version.)
param([string]$Action = "menu")
$Hote = "aibeast"
$Lab  = "~/.local/bin/lab"
$RegexProjet  = '^[a-z0-9][a-z0-9_-]{0,40}$'
$RegexBranche = '^agent/[A-Za-z0-9._-]+$'

# Runs `lab ...` on AiBeast. -Tty: interactive terminal (needed for Hermes and long actions under tmux).
# ClearAllForwardings: without it, ssh tries to open the tunnels that are already open and stops (ExitOnForwardFailure).
# The arguments passed here only contain names already validated (projects, branches, languages).
function Invoke-Lab {
    param([string]$Commande, [switch]$Tty)
    if ($Tty) {
        # Interactive terminal: Start-Process gives ssh the console itself (a plain "& ssh | Out-Host" would break tmux and Hermes).
        $arguments = "-t -o ClearAllForwardings=yes $Hote `"$Lab $Commande`""
        $proc = Start-Process -FilePath "ssh" -ArgumentList $arguments -NoNewWindow -Wait -PassThru
        return $proc.ExitCode
    }
    & ssh -o ClearAllForwardings=yes $Hote "$Lab $Commande" | Out-Host
    return $LASTEXITCODE
}

# Same thing but returns the text (one line per item) instead of displaying it.
function Get-Lab {
    param([string]$Commande)
    $sortie = & ssh -o ClearAllForwardings=yes $Hote "$Lab $Commande"
    return @($sortie | Where-Object { $_ -ne $null -and "$_".Trim() -ne "" })
}

function Test-Connexion {
    & ssh -o BatchMode=yes -o ConnectTimeout=8 -o ClearAllForwardings=yes $Hote "echo ok" 2>$null | Out-Null
    if ($LASTEXITCODE -ne 0) {
        Write-Host "Cannot reach AiBeast over SSH." -ForegroundColor Yellow
        Write-Host "Possible causes: VPN not connected, SSH key not loaded, 'Host aibeast' entry missing from $env:USERPROFILE\.ssh\config (see lab client)."
        Write-Host "Manual test: ssh aibeast"
        return $false
    }
    return $true
}

function Attendre { Write-Host ""; Read-Host "Press Enter to continue" | Out-Null }

function Ouvrir-Navigateur([string]$Url) {
    $port = ([Uri]$Url).Port
    if ((Test-NetConnection 127.0.0.1 -Port $port -WarningAction SilentlyContinue).TcpTestSucceeded) { Start-Process $Url }
    else { Write-Host "The tunnel to $Url is not open: run Ouvrir-AiBeast.bat first." -ForegroundColor Yellow }
}

function Action-Images {
    Write-Host "Images mode: unloads the language model, starts ComfyUI (up to 3 minutes)..." -ForegroundColor Cyan
    $rc = Invoke-Lab "mode images"
    if ($rc -eq 0) { Ouvrir-Navigateur "http://127.0.0.1:8188" }
    Write-Host "To go back to the language models: AiBeast-Normal.bat" -ForegroundColor Cyan
}

function Action-Hermes {
    while ($true) {
        Write-Host ""
        Write-Host "=== Hermes: development ===" -ForegroundColor Cyan
        Write-Host " 1) Review and merge the agent's work"
        Write-Host " 2) Open Hermes in a project"
        Write-Host " 3) New project"
        Write-Host " 0) Back"
        $c = Read-Host "Choice"
        switch ($c) {
            "1" { Hermes-Fusion }
            "2" { Hermes-Ouvrir }
            "3" { Hermes-Nouveau }
            "0" { return }
        }
    }
}

function Hermes-Fusion {
    $lignes = Get-Lab "dev pending"
    $items = @()
    foreach ($l in $lignes) {
        $p = "$l" -split "`t"
        # The names come from AiBeast (partly chosen by the agent): they are validated again here before going into a command.
        if ($p.Count -eq 3 -and $p[0] -match $RegexProjet -and $p[1] -match $RegexBranche -and $p[2] -match '^\d+$') {
            $items += [pscustomobject]@{ Projet = $p[0]; Branche = $p[1]; Commits = $p[2] }
        }
    }
    if ($items.Count -eq 0) { Write-Host "No agent branch to review." -ForegroundColor Green; return }
    for ($i = 0; $i -lt $items.Count; $i++) {
        Write-Host (" {0}) {1}  {2}  ({3} commit(s))" -f ($i + 1), $items[$i].Projet, $items[$i].Branche, $items[$i].Commits)
    }
    $n = Read-Host "Number (Enter to cancel)"
    if ($n -notmatch '^\d+$' -or [int]$n -lt 1 -or [int]$n -gt $items.Count) { return }
    $it = $items[[int]$n - 1]
    Write-Host ""
    Invoke-Lab "dev review $($it.Projet) $($it.Branche)" | Out-Null
    if ((Read-Host "See the full diff? (y/N)") -match '^[yYoO]') {
        Invoke-Lab "dev review $($it.Projet) $($it.Branche) --diff" | Out-Null
    }
    Write-Host ""
    Write-Host "Merging first runs the tests again in the sandbox; if they fail, nothing is merged." -ForegroundColor Cyan
    if ((Read-Host "Merge $($it.Branche) into main? Have you reviewed the diff? (y/N)") -match '^[yYoO]') {
        Invoke-Lab "dev merge $($it.Projet) $($it.Branche) --yes" | Out-Null
    } else { Write-Host "Cancelled." }
}

function Hermes-Ouvrir {
    $noms = @(Get-Lab "dev names" | Where-Object { $_ -match $RegexProjet })
    if ($noms.Count -eq 0) { Write-Host "No project: create one (choice 3)." -ForegroundColor Yellow; return }
    for ($i = 0; $i -lt $noms.Count; $i++) { Write-Host (" {0}) {1}" -f ($i + 1), $noms[$i]) }
    $n = Read-Host "Number (Enter to cancel)"
    if ($n -notmatch '^\d+$' -or [int]$n -lt 1 -or [int]$n -gt $noms.Count) { return }
    Write-Host "Hermes opens in this terminal; /exit to quit it." -ForegroundColor Cyan
    Invoke-Lab "dev start $($noms[[int]$n - 1])" -Tty | Out-Null
}

function Hermes-Nouveau {
    $nom = Read-Host "Project name (lower case, digits, - and _)"
    if ($nom -notmatch $RegexProjet) { Write-Host "Invalid name." -ForegroundColor Yellow; return }
    $lang = Read-Host "Language: python, node, shell or other (Enter = python)"
    if ([string]::IsNullOrWhiteSpace($lang)) { $lang = "python" }
    if ($lang -notin @("python", "node", "shell", "other", "autre")) { Write-Host "Unknown language." -ForegroundColor Yellow; return }
    Invoke-Lab "dev new $nom $lang" | Out-Null
}

function Executer([string]$a) {
    switch ($a) {
        "images"  { Action-Images }
        "normal"  { Invoke-Lab "mode normal" | Out-Null }
        "agents"  { Invoke-Lab "mode agents" | Out-Null }
        "status"  { Invoke-Lab "mode status" | Out-Null }
        "doctor"  { Invoke-Lab "doctor" | Out-Null }
        "update"  { Write-Host "Update (tmux session 'lab-update': it continues if the connection drops)..." -ForegroundColor Cyan; Invoke-Lab "tmux update" -Tty | Out-Null }
        "backup"  { Write-Host "Backup (tmux session 'lab-backup')..." -ForegroundColor Cyan; Invoke-Lab "tmux backup" -Tty | Out-Null }
        "hermes"  { Action-Hermes }
        "portail" { & (Join-Path $PSScriptRoot "Ouvrir-AiBeast.ps1") }
        default   { Write-Host "Unknown action: $a" -ForegroundColor Yellow }
    }
}

if (-not (Test-Connexion)) { Read-Host "Press Enter to close" | Out-Null; exit 1 }

if ($Action -ne "menu") {
    Executer $Action
    Write-Host ""
    Read-Host "Done. Press Enter to close" | Out-Null
    exit 0
}

while ($true) {
    Clear-Host
    Write-Host "=== AiBeast ===" -ForegroundColor Cyan
    Write-Host " 1) IMAGES mode  (unloads the model, starts ComfyUI)"
    Write-Host " 2) NORMAL mode  (stops ComfyUI, restores everything)"
    Write-Host " 3) AGENTS mode  (frees VRAM for Hermes)"
    Write-Host " 4) State        (mode, VRAM, loaded models)"
    Write-Host " 5) Health       (lab doctor)"
    Write-Host " 6) Update       (Docker images)"
    Write-Host " 7) Backup"
    Write-Host " 8) Hermes       (review / merge / open a project)"
    Write-Host " 9) Open the portal in the browser"
    Write-Host " 0) Quit"
    $c = Read-Host "Choice"
    $map = @{ "1" = "images"; "2" = "normal"; "3" = "agents"; "4" = "status"; "5" = "doctor"; "6" = "update"; "7" = "backup"; "8" = "hermes"; "9" = "portail" }
    if ($c -eq "0") { break }
    if ($map.ContainsKey($c)) { Executer $map[$c]; if ($c -ne "8") { Attendre } }
}
